CREATE DATABASE IF NOT EXISTS benchops_mf_qp04;
CREATE TABLE IF NOT EXISTS benchops_mf_qp04.mf_qp04_order_events_a (id BIGINT NOT NULL PRIMARY KEY, routing_key VARCHAR(16) NOT NULL, status VARCHAR(16) NOT NULL, amount DECIMAL(12,2) NOT NULL, payload VARCHAR(64) NOT NULL, KEY idx_mf_qp04_routing_key (routing_key), KEY idx_mf_qp04_status (status));
INSERT INTO benchops_mf_qp04.mf_qp04_order_events_a (id, routing_key, status, amount, payload) SELECT n, IF(n <= 100, 'r29', 'r03'), IF(n > 100 AND n <= 200, 'pending', 'closed'), CAST(n AS DECIMAL(12,2)), CONCAT('bootstrap-', n) FROM (SELECT n FROM (WITH RECURSIVE head(h) AS (SELECT 1 UNION ALL SELECT h + 1 FROM head WHERE h < 10), tail(t) AS (SELECT 1 UNION ALL SELECT t + 1 FROM tail WHERE t < 200) SELECT (head.h - 1) * 200 + tail.t AS n FROM head CROSS JOIN tail WHERE (head.h - 1) * 200 + tail.t <= 2000) source) source;
ANALYZE TABLE benchops_mf_qp04.mf_qp04_order_events_a;
