CREATE TABLE IF NOT EXISTS benchops_mf_qp04.mf_qp04_compaction_buffer (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, routing_key VARCHAR(16) NOT NULL, status VARCHAR(16) NOT NULL, amount DECIMAL(12,2) NOT NULL, payload VARCHAR(240) NOT NULL, KEY idx_mf_qp04_compaction_routing (routing_key), KEY idx_mf_qp04_compaction_status (status), KEY idx_mf_qp04_compaction_payload (payload));
INSERT INTO benchops_mf_qp04.mf_qp04_compaction_buffer (routing_key, status, amount, payload) SELECT IF(n % 2 = 0, 'r91', 'r92'), IF(n % 3 = 0, 'closed', 'open'), CAST(n AS DECIMAL(12,2)), RPAD('initial-compaction-', 240, 'x') FROM (SELECT n FROM (WITH RECURSIVE head(h) AS (SELECT 1 UNION ALL SELECT h + 1 FROM head WHERE h < 100), tail(t) AS (SELECT 1 UNION ALL SELECT t + 1 FROM tail WHERE t < 200) SELECT (head.h - 1) * 200 + tail.t AS n FROM head CROSS JOIN tail WHERE (head.h - 1) * 200 + tail.t <= 20000) source) source;
ANALYZE TABLE benchops_mf_qp04.mf_qp04_compaction_buffer;
